import os
import ast

def find_legacy_auth_calls():
    app_dir = "app"
    for root, _, files in os.walk(app_dir):
        for file in files:
            if not file.endswith(".py"):
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
            if "legacy_auth" not in content:
                continue
            try:
                tree = ast.parse(content, filename=path)
            except SyntaxError:
                continue

            # We want to find each legacy_auth call and print its enclosing function
            class Visitor(ast.NodeVisitor):
                def __init__(self):
                    self.current_function = None

                def visit_FunctionDef(self, node):
                    old_func = self.current_function
                    self.current_function = node
                    self.generic_visit(node)
                    self.current_function = old_func

                def visit_Call(self, node):
                    if isinstance(node.func, ast.Name) and node.func.id == "legacy_auth":
                        # We found a call! Let's print function source
                        func_name = self.current_function.name if self.current_function else "global"
                        func_src = ast.get_source_segment(content, self.current_function) if self.current_function else ""
                        print(f"FILE: {path}")
                        print(f"FUNCTION: {func_name}")
                        print("SOURCE:")
                        print(func_src)
                        print("-" * 40)
                    self.generic_visit(node)

            Visitor().visit(tree)

if __name__ == "__main__":
    find_legacy_auth_calls()

