import os
import ast

def test_classification():
    app_dir = "app"
    indicators = ['create', 'update', 'delete', 'save', 'write', 'post_', 'put', 'patch', 'created', 'updated', 'deleted']

    write_endpoints = []
    read_endpoints = []

    for root, _, files in os.walk(app_dir):
        for file in files:
            if not file.endswith(".py"):
                continue
            path = os.path.join(root, file)
            if path == "app/auth.py":
                continue
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
            if "legacy_auth" not in content:
                continue

            tree = ast.parse(content, filename=path)

            class Visitor(ast.NodeVisitor):
                def __init__(self):
                    self.current_function = None

                def visit_FunctionDef(self, node):
                    old_func = self.current_function
                    self.current_function = node
                    self.generic_visit(node)
                    self.current_function = old_func

                def visit_Call(self, node):
                    if isinstance(node.func, ast.Name) and node.func.id == "legacy_auth":
                        func_name = self.current_function.name if self.current_function else "global"
                        func_src = ast.get_source_segment(content, self.current_function) if self.current_function else ""

                        # Apply classification
                        content_to_check = (path + "\n" + func_src).lower()
                        is_write = any(ind in content_to_check for ind in indicators)

                        entry = f"{path} -> {func_name}"
                        if is_write:
                            write_endpoints.append(entry)
                        else:
                            read_endpoints.append(entry)
                    self.generic_visit(node)

            Visitor().visit(tree)

    print(f"WRITE ENDPOINTS ({len(write_endpoints)}):")
    for we in sorted(write_endpoints):
        print(f"  {we}")

    print(f"\nREAD ENDPOINTS ({len(read_endpoints)}):")
    for re in sorted(read_endpoints):
        print(f"  {re}")

if __name__ == "__main__":
    test_classification()
